/* Scoped by the static .three-ripple class (set on the root by Hooks).
   Per-instance {{id}} interpolation is unreliable in preview/publish builds,
   so no template interpolation is used in this file. */

.three-ripple {
  position: relative;
  display: block;
  box-sizing: border-box;
  flex: 1 1 auto;
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 16rem;
  overflow: hidden;
  isolation: isolate;
  background: var(--color-neutral-950);
}

.three-ripple .three-ripple__source,
.three-ripple .three-ripple__canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.three-ripple .three-ripple__source {
  z-index: 1;
}

.three-ripple .three-ripple__source img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
}

.three-ripple .three-ripple__canvas {
  z-index: 2;
  display: block;
  opacity: 0;
  pointer-events: none;
  transition: opacity 240ms ease;
}

.three-ripple.is-ready .three-ripple__canvas {
  opacity: 1;
}

.three-ripple.is-ready .three-ripple__source {
  visibility: hidden;
}


@media (prefers-reduced-motion: reduce) {
  .three-ripple .three-ripple__canvas {
    transition: none;
  }
}

(() => {
  const SELECTOR = '[data-three-ripple]';
  const THREE_URL = 'https://cdn.jsdelivr.net/npm/three@0.165.0/build/three.module.min.js';

  window.__elementsThreeRipple = window.__elementsThreeRipple || {
    module: null,
    observer: null
  };

  const shared = window.__elementsThreeRipple;
  const loadThree = () => shared.module || (shared.module = import(THREE_URL));

  const waitForImage = (host) => new Promise((resolve) => {
    const started = performance.now();

    const check = () => {
      const image = host.querySelector('.three-ripple__source img');
      if (image && image.complete && image.naturalWidth > 0) {
        resolve(image);
        return;
      }
      if (performance.now() - started > 10000 || !host.isConnected) {
        resolve(null);
        return;
      }
      requestAnimationFrame(check);
    };

    check();
  });

  const init = async (host) => {
    if (host.dataset.rippleInitialised === 'true') return;
    host.dataset.rippleInitialised = 'true';

    const image = await waitForImage(host);
    if (!image || !host.isConnected) {
      host.dataset.rippleInitialised = 'false';
      return;
    }

    let THREE;
    try {
      THREE = await loadThree();
    } catch (error) {
      console.warn('Three.js Image Ripple: Three.js could not be loaded.', error);
      host.dataset.rippleInitialised = 'false';
      return;
    }

    const canvas = host.querySelector('.three-ripple__canvas');
    if (!canvas || !host.isConnected) return;

    const renderer = new THREE.WebGLRenderer({
      canvas,
      alpha: false,
      antialias: false,
      powerPreference: 'high-performance'
    });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.outputColorSpace = THREE.SRGBColorSpace;

    const scene = new THREE.Scene();
    const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);
    const geometry = new THREE.PlaneGeometry(2, 2);
    const texture = new THREE.Texture(image);
    // NoColorSpace: skip sRGB decode so the raw ShaderMaterial passes the
    // image pixels through unchanged (custom shaders get no output encoding,
    // so a decoded texture would display too dark).
    texture.colorSpace = THREE.NoColorSpace;
    texture.minFilter = THREE.LinearFilter;
    texture.magFilter = THREE.LinearFilter;
    texture.needsUpdate = true;

    const uniforms = {
      uTexture: { value: texture },
      uTime: { value: 0 },
      uPointer: { value: new THREE.Vector2(0.5, 0.5) },
      uTarget: { value: new THREE.Vector2(0.5, 0.5) },
      uResolution: { value: new THREE.Vector2(1, 1) },
      uImageSize: { value: new THREE.Vector2(image.naturalWidth, image.naturalHeight) },
      uStrength: { value: Number(host.dataset.strength) || 0.025 },
      uSpeed: { value: Number(host.dataset.speed) || 2.2 },
      uFrequency: { value: Number(host.dataset.frequency) || 28 },
      uDecay: { value: Number(host.dataset.decay) || 7 },
      uActivity: { value: 0 },
      uIdle: { value: host.dataset.idle === 'true' ? 1 : 0 },
      uIdleStrength: { value: Number(host.dataset.idleStrength) || 0.012 }
    };

    const material = new THREE.ShaderMaterial({
      uniforms,
      vertexShader: `
        varying vec2 vUv;
        void main() {
          vUv = uv;
          gl_Position = vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        precision highp float;
        uniform sampler2D uTexture;
        uniform float uTime;
        uniform vec2 uPointer;
        uniform vec2 uResolution;
        uniform vec2 uImageSize;
        uniform float uStrength;
        uniform float uSpeed;
        uniform float uFrequency;
        uniform float uDecay;
        uniform float uActivity;
        uniform float uIdle;
        uniform float uIdleStrength;
        varying vec2 vUv;

        vec2 coverUv(vec2 uv, vec2 screenSize, vec2 imageSize) {
          float screenRatio = screenSize.x / screenSize.y;
          float imageRatio = imageSize.x / imageSize.y;
          vec2 scale = vec2(1.0);
          if (screenRatio > imageRatio) {
            scale.y = imageRatio / screenRatio;
          } else {
            scale.x = screenRatio / imageRatio;
          }
          return (uv - 0.5) * scale + 0.5;
        }

        void main() {
          vec2 aspect = vec2(uResolution.x / max(uResolution.y, 1.0), 1.0);
          vec2 delta = (vUv - uPointer) * aspect;
          float distanceToPointer = length(delta);
          float wave = sin(distanceToPointer * uFrequency - uTime * uSpeed);
          float falloff = exp(-distanceToPointer * uDecay);
          float idleTime = uTime * 0.9;
          vec2 idleWave = vec2(
            sin(vUv.y * 12.0 + idleTime) + 0.5 * sin(vUv.y * 23.0 - idleTime * 1.3),
            cos(vUv.x * 14.0 - idleTime * 0.8) + 0.5 * sin(vUv.x * 21.0 + idleTime * 1.1)
          ) * uIdleStrength * uIdle * (1.0 - uActivity * 0.6);
          vec2 direction = normalize(delta + vec2(0.0001));
          vec2 displacement = direction * wave * falloff * uStrength * uActivity;
          displacement += idleWave;
          vec2 uv = coverUv(vUv + displacement, uResolution, uImageSize);
          gl_FragColor = texture2D(uTexture, clamp(uv, 0.001, 0.999));
        }
      `
    });

    const mesh = new THREE.Mesh(geometry, material);
    scene.add(mesh);

    let width = 1;
    let height = 1;
    let frame = 0;
    let last = performance.now();
    let targetActivity = 0;
    let destroyed = false;
    const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');

    const resize = () => {
      width = Math.max(host.clientWidth, 1);
      height = Math.max(host.clientHeight, 1);
      renderer.setSize(width, height, false);
      uniforms.uResolution.value.set(width, height);
    };

    const updatePointer = (event) => {
      const rect = host.getBoundingClientRect();
      if (!rect.width || !rect.height) return;
      const isInside = event.clientX >= rect.left && event.clientX <= rect.right && event.clientY >= rect.top && event.clientY <= rect.bottom;
      if (!isInside) {
        targetActivity = 0;
        return;
      }
      uniforms.uTarget.value.set(
        (event.clientX - rect.left) / rect.width,
        1 - (event.clientY - rect.top) / rect.height
      );
      targetActivity = reducedMotion.matches ? 0 : 1;
    };

    const leave = () => {
      targetActivity = 0;
    };

    const render = (now) => {
      if (destroyed) return;
      frame = requestAnimationFrame(render);
      const delta = Math.min((now - last) / 1000, 0.05);
      last = now;
      uniforms.uTime.value += delta;
      uniforms.uPointer.value.lerp(uniforms.uTarget.value, 0.14);
      uniforms.uActivity.value += (targetActivity - uniforms.uActivity.value) * 0.08;
      renderer.render(scene, camera);
    };

    const resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(host);
    window.addEventListener('pointermove', updatePointer, { passive: true });
    window.addEventListener('pointerdown', updatePointer, { passive: true });

    const destroy = () => {
      if (destroyed) return;
      destroyed = true;
      cancelAnimationFrame(frame);
      resizeObserver.disconnect();
      window.removeEventListener('pointermove', updatePointer);
      window.removeEventListener('pointerdown', updatePointer);
      texture.dispose();
      material.dispose();
      geometry.dispose();
      renderer.dispose();
      host.classList.remove('is-ready');
      delete host.dataset.rippleInitialised;
    };

    host.__destroyThreeRipple?.();
    host.__destroyThreeRipple = destroy;
    resize();
    host.classList.add('is-ready');
    frame = requestAnimationFrame(render);
  };

  const scan = (root = document) => {
    if (root.matches?.(SELECTOR)) init(root);
    root.querySelectorAll?.(SELECTOR).forEach(init);
  };

  scan();

  if (!shared.observer) {
    shared.observer = new MutationObserver((mutations) => {
      mutations.forEach((mutation) => {
        mutation.addedNodes.forEach((node) => {
          if (node.nodeType === 1) scan(node);
        });
        mutation.removedNodes.forEach((node) => {
          if (node.nodeType !== 1) return;
          if (node.matches?.(SELECTOR)) node.__destroyThreeRipple?.();
          node.querySelectorAll?.(SELECTOR).forEach((host) => host.__destroyThreeRipple?.());
        });
      });
    });
    shared.observer.observe(document.documentElement, { childList: true, subtree: true });
  }
})();

const transformHook = (rw) => {
  const clamp = (value, min, max, fallback) => {
    const number = Number(value);
    return Number.isFinite(number) ? Math.min(Math.max(number, min), max) : fallback;
  };

  const id = rw.node.id;

  rw.setRootElement({
    as: 'div',
    class: `component-${id} three-ripple`,
    args: {
      'data-three-ripple': '',
      'data-edit': rw.project.mode === 'edit' ? 'true' : 'false',
      'data-strength': String(clamp(rw.props.rippleStrength, 2, 80, 25) / 1000),
      'data-speed': String(clamp(rw.props.rippleSpeed, 1, 8, 2)),
      'data-frequency': String(clamp(rw.props.rippleFrequency, 6, 70, 28)),
      'data-decay': String(clamp(rw.props.rippleDecay, 2, 18, 7)),
      'data-idle': rw.props.idleMotion === false ? 'false' : 'true',
      'data-idle-strength': String(clamp(rw.props.idleStrength, 1, 50, 12) / 1000)
    }
  });

  rw.setProps({
    edit: rw.project.mode === 'edit',
    rippleStrength: clamp(rw.props.rippleStrength, 2, 80, 25),
    rippleSpeed: clamp(rw.props.rippleSpeed, 1, 8, 2),
    rippleFrequency: clamp(rw.props.rippleFrequency, 6, 70, 28),
    rippleDecay: clamp(rw.props.rippleDecay, 2, 18, 7),
    idleStrength: clamp(rw.props.idleStrength, 1, 50, 12)
  });
};

exports.transformHook = transformHook;

