/* Scoped by the static .status-dot class. Per-instance {{id}}
   interpolation is unreliable in preview/publish builds, so the size
   is passed as an inline --dot-size variable from the template. */

.status-dot {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--dot-size, 8px);
  height: var(--dot-size, 8px);
  flex-shrink: 0;
}

/* Solid core dot */
.status-dot .status-dot__core {
  position: relative;
  z-index: 1;
  width: 100%;
  height: 100%;
  border-radius: 9999px;
}

/* Expanding/fading ring */
.status-dot .status-dot__ring {
  position: absolute;
  inset: 0;
  border-radius: 9999px;
  opacity: 0.6;
  animation: status-dot-pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
}

@keyframes status-dot-pulse {
  0%, 100% {
    transform: scale(1);
    opacity: 0.6;
  }
  50% {
    transform: scale(2.2);
    opacity: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .status-dot .status-dot__ring {
    animation: none;
  }
}

